import{_ as n,o as e,c as s,a2 as i}from"./chunks/framework.XXezeKOl.js";const g=JSON.parse('{"title":"RAG 原始论文","description":"精读 Retrieval-Augmented Generation：把检索器和生成模型结合起来，让模型的知识可以更新、可以溯源。","frontmatter":{"title":"RAG 原始论文","description":"精读 Retrieval-Augmented Generation：把检索器和生成模型结合起来，让模型的知识可以更新、可以溯源。"},"headers":[],"relativePath":"papers/rag.md","filePath":"papers/rag.md","lastUpdated":null}'),l={name:"papers/rag.md"};function r(t,a,o,p,d,u){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="rag-原始论文" tabindex="-1">RAG 原始论文 <a class="header-anchor" href="#rag-原始论文" aria-label="Permalink to &quot;RAG 原始论文&quot;">​</a></h1><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li>标题：Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks</li><li>作者：Patrick Lewis、Ethan Perez、Aleksandra Piktus、Fabio Petroni、Vladimir Karpukhin、Naman Goyal、Heinrich Küttler、Mike Lewis、Wen-tau Yih、Tim Rocktäschel、Sebastian Riedel、Douwe Kiela（Facebook AI Research、University College London、New York University）</li><li>年份：2020（NeurIPS 2020）</li><li>链接：<a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noreferrer">arXiv:2005.11401</a></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>把一个可检索的外部文档库（非参数记忆）和一个生成模型（参数记忆）组合起来，生成答案前先检索相关文档，并把检索器和生成器一起端到端训练，在知识密集型任务上取得了更好、更可溯源的结果。</p><h2 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h2><p>预训练语言模型把大量知识存在参数里，但这种&quot;参数记忆&quot;有几个根本问题：</p><ul><li><strong>难以更新：</strong> 世界上的知识变了，只能重新训练或微调模型。</li><li><strong>难以溯源：</strong> 模型给出一个答案，你无法知道它依据的是哪份资料。</li><li><strong>会产生幻觉：</strong> 模型对不确定的知识也会给出流畅但错误的回答。</li></ul><p>此前已有一些&quot;检索加阅读&quot;的方法，但多数只能从文档中抽取答案片段，不能自由生成；或者检索与生成分开训练。作者想要一个通用方案：既能自由生成文本，又能利用可替换的外部知识。</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>RAG 由两部分组成：</p><ul><li><strong>检索器：</strong> 基于 DPR（Dense Passage Retrieval）的双塔模型，把问题和文档都编码成向量，用最大内积搜索从 Wikipedia 切分出的大量段落中找出 Top-K 相关段落。</li><li><strong>生成器：</strong> 一个预训练的 seq2seq 模型（BART），把问题和检索到的段落拼在一起作为输入，生成答案。</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                       离线：Wikipedia 段落 ──▶ 文档编码器 ──▶ 向量索引</span></span>
<span class="line"><span>                                                                │</span></span>
<span class="line"><span> 在线：                                                          ▼</span></span>
<span class="line"><span> ┌──────┐   ┌────────────┐   问题向量   ┌───────────────────────────┐</span></span>
<span class="line"><span> │ 问题 │──▶│ 问题编码器  │ ──────────▶ │ 最大内积搜索，取 Top-K 段落 │</span></span>
<span class="line"><span> └──────┘   └────────────┘             └───────────────────────────┘</span></span>
<span class="line"><span>     │                                          │ z1, z2, ... zK</span></span>
<span class="line"><span>     │                                          ▼</span></span>
<span class="line"><span>     │                         ┌────────────────────────────────────┐</span></span>
<span class="line"><span>     └────────────────────────▶│ 生成器 (BART)：问题 + 每个段落 ──▶ 答案 │</span></span>
<span class="line"><span>                               │ 对 K 个段落的生成概率做边缘化        │</span></span>
<span class="line"><span>                               └────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>论文提出两种变体：</p><ul><li><strong>RAG-Sequence：</strong> 整个答案基于同一个检索段落生成，再对各个段落的结果加权合并。</li><li><strong>RAG-Token：</strong> 生成每个 Token 时都可以依据不同的段落，适合需要综合多份资料的答案。</li></ul><p>训练时，检索到哪个段落被当作隐变量，问题编码器和生成器一起微调；文档编码器和索引保持固定，避免频繁重建索引。</p><h2 id="关键实验结论" tabindex="-1">关键实验结论 <a class="header-anchor" href="#关键实验结论" aria-label="Permalink to &quot;关键实验结论&quot;">​</a></h2><ul><li><strong>开放域问答：</strong> 在多个开放域问答数据集上，RAG 取得了当时的最好成绩，超过了纯参数模型和只能抽取答案的检索方法。即使正确答案不在检索段落中，RAG 也能生成正确答案。</li><li><strong>生成更符合事实：</strong> 在问题生成等开放生成任务上，人工评估认为 RAG 的输出比纯参数的 BART 更符合事实、更具体。</li><li><strong>事实核查：</strong> 在 FEVER 事实核查任务上，接近使用复杂流水线和额外监督的专门系统。</li><li><strong>知识可以热替换：</strong> 把索引从旧版 Wikipedia 换成新版，不用重新训练，模型就能回答关于新知识的问题。这直接展示了非参数记忆的优势。</li></ul><h2 id="对-agent-开发的启发" tabindex="-1">对 Agent 开发的启发 <a class="header-anchor" href="#对-agent-开发的启发" aria-label="Permalink to &quot;对 Agent 开发的启发&quot;">​</a></h2><ul><li><strong>知识放在模型外面。</strong> 企业知识、最新数据、用户私有文档，应该通过检索提供，而不是寄希望于模型记住或频繁微调。</li><li><strong>检索质量决定答案质量。</strong> RAG 的效果上限由检索器决定。今天工程上的切分、混合检索、重排，都是在提升这一环。</li><li><strong>可溯源是重要的产品能力。</strong> 答案附带检索来源，用户可以核实，这对企业应用尤其关键。</li><li><strong>今天的 RAG 和论文里的 RAG 已经不一样。</strong> 论文是端到端训练的检索器加生成器；今天常见做法是现成的 Embedding 模型、向量数据库加大模型 API，组件之间不联合训练。思想一致，实现方式不同。</li><li><strong>从固定检索到 Agentic RAG。</strong> 论文中每个问题检索一次；今天的 Agent 可以把检索当成工具，自己决定检索什么、检索几次。</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>检索器和生成器需要联合训练，对普通应用开发者门槛较高。</li><li>文档编码器和索引固定，检索器的能力受限于预训练效果。</li><li>每个问题只检索一次，无法处理需要多步检索、逐步推理的复杂问题。</li><li>生成器的上下文长度有限，能利用的段落数量少。</li><li>检索到错误或有偏见的内容时，生成结果也会出错，模型缺乏判断资料可信度的机制。</li></ul><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/guide/09-rag/overview">RAG 全景</a></li><li><a href="/guide/02-llm-basics/embeddings">Embedding 与向量语义</a></li><li><a href="/guide/09-rag/vector-db">向量数据库</a></li><li><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></li><li><a href="/guide/09-rag/advanced-rag">GraphRAG 与 Agentic RAG</a></li><li><a href="/guide/09-rag/rag-eval">RAG 评估</a></li><li>实战项目：<a href="/projects/04-pdf-rag">04 个人 PDF 知识库</a></li></ul>`,24)])])}const h=n(l,[["render",r]]);export{g as __pageData,h as default};
